// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MyContract} from "../src/MyContract.sol";

contract InvMutTest is Test {
    MyContract c;
    Recorder rec;

    function setUp() public {
        c = new MyContract();
        rec = new Recorder();
    }

    function testFuzz_property(uint256 amount, address actor) public {
        vm.assume(amount > 0);
        vm.assume(amount < type(uint256).max);
        vm.assume(actor != address(0));

        // Fund the contract with exactly the requested amount so the
        // reference's transfer(amount) always succeeds (reference must hold
        // for EVERY admissible input).
        vm.deal(address(c), amount);

        // owner is whoever deployed c in setUp, i.e. address(this);
        // actor is a fuzzed caller we use for the call (it is not the owner,
        // so we must prank the owner to stay in the admissible domain).
        vm.prank(address(this));
        c.sendTo(address(rec), amount);

        assertTrue(address(rec).balance == amount);
    }
}

contract Recorder {
    receive() external payable {}
}
